local UIViewModel = require("UI/UIViewModel")
local MsgTipsUtil = require("Utils/MsgTipsUtil")
local ProtoCS = require("Protocol/ProtoCS")
local HouseFlagCfg = require("TableCfg/HouseFlagCfg")
local HouseLocalDef = require("Game/House/HouseLocalDef")
local MathUtil = require("Utils/MathUtil")

local HouseInfoSettingsWinVM = LuaClass(UIViewModel)
local LSTR = _G.LSTR

function HouseInfoSettingsWinVM:Ctor()
    self.VisitPrivilege = nil
    self.PanelHouseInfoVisible = true
    self.PanelTagVisible = false
    self.PanelViewPermissionsVisible = false
    self.PanelOtherVisible = false
    self.HouseTagSelect = {}
    self.ModifyTypes = {}
    self.DestoryHouseConditions = {}
    self.GiveUpLandConditions = {}
    self.TagNum = 0
    self.HouseID = nil
    self.HouseType = nil
    self.CacheTagTable = {}
    self.OwnerID = nil
